export interface Record {
    id: number;
    name: string;
    severity: Severity;
    signed: Signed;
    flags: RecordFlags;
    labels: Label[];
    values: number[];
    trailer: number;
    pair: string[];
    nested: Uint8Array[];
    severities: Severity[];
    matrix: number[][];
}

export const Record = Object.freeze({
    write(writer: PackedWriter, value: Record): void {
        writer.uint32(value.id, true);
        writer.text(value.name, 2, true);
        writer.uint8(enumValue(Severity, value.severity));
        writer.int16(enumValue(Signed, value.signed), true);
        let flagsBits0 = 0n;
        flagsBits0 |= (value.flags.active ? 1n : 0n);
        flagsBits0 |= ((BigInt(value.flags.level) & 0x7n) << 1n);
        writer.word(flagsBits0, 1, true);
        if (value.labels.length > 4) throw new RangeError(`value.labels holds more than its maximum of 4 items`);
        writer.length(value.labels.length, 1, true);
        for (const item of value.labels) {
            writer.text(item.name, 1, true);
            writer.float32(item.weight, true);
        }
        if (value.values.length > 4) throw new RangeError(`value.values holds more than its maximum of 4 items`);
        writer.length(value.values.length, 2, true);
        for (const item of value.values) {
            writer.int16(item, true);
        }
        writer.uint16(value.trailer, false);
        if (value.pair.length !== 2) throw new RangeError(`value.pair must hold 2 items, not ${value.pair.length}`);
        for (const item of value.pair) {
            writer.text(item, 1, true);
        }
        if (value.nested.length > 4) throw new RangeError(`value.nested holds more than its maximum of 4 items`);
        writer.length(value.nested.length, 1, true);
        for (const item of value.nested) {
            writer.bytesOf(item, 4, true);
        }
        if (value.severities.length > 4) throw new RangeError(`value.severities holds more than its maximum of 4 items`);
        writer.length(value.severities.length, 1, true);
        for (const item of value.severities) {
            writer.uint8(enumValue(Severity, item));
        }
        if (value.matrix.length !== 2) throw new RangeError(`value.matrix must hold 2 items, not ${value.matrix.length}`);
        for (const item of value.matrix) {
            if (item.length !== 2) throw new RangeError(`item must hold 2 items, not ${item.length}`);
            for (const item1 of item) {
                writer.int16(item1, true);
            }
        }
    },

    read(reader: PackedReader): Record {
        const value = {} as Record;
        value.id = reader.uint32(true);
        value.name = reader.text(2, true);
        value.severity = enumName(Severity, reader.uint8(), "Severity");
        value.signed = enumName(Signed, reader.int16(true), "Signed");
        value.flags = {} as RecordFlags;
        const flagsBits0 = reader.word(1, true);
        value.flags.active = (flagsBits0 & 0x1n) !== 0n;
        value.flags.level = Number(((flagsBits0 >> 1n) & 0x7n));
        {
            const count0 = reader.length(1, true);
            if (count0 > 4) throw new RangeError(`value.labels holds more than its maximum of 4 items`);
            value.labels = [];
            for (let itemIndex = 0, itemCount = count0; itemIndex < itemCount; itemIndex++) {
                let item: Label;
                item = {} as Label;
                item.name = reader.text(1, true);
                item.weight = reader.float32(true);
                value.labels.push(item);
            }
        }
        {
            const count0 = reader.length(2, true);
            if (count0 > 4) throw new RangeError(`value.values holds more than its maximum of 4 items`);
            value.values = [];
            for (let itemIndex = 0, itemCount = count0; itemIndex < itemCount; itemIndex++) {
                let item: number;
                item = reader.int16(true);
                value.values.push(item);
            }
        }
        value.trailer = reader.uint16(false);
        value.pair = [];
        for (let itemIndex = 0, itemCount = 2; itemIndex < itemCount; itemIndex++) {
            let item: string;
            item = reader.text(1, true);
            value.pair.push(item);
        }
        {
            const count0 = reader.length(1, true);
            if (count0 > 4) throw new RangeError(`value.nested holds more than its maximum of 4 items`);
            value.nested = [];
            for (let itemIndex = 0, itemCount = count0; itemIndex < itemCount; itemIndex++) {
                let item: Uint8Array;
                item = reader.bytesOf(4, true);
                value.nested.push(item);
            }
        }
        {
            const count0 = reader.length(1, true);
            if (count0 > 4) throw new RangeError(`value.severities holds more than its maximum of 4 items`);
            value.severities = [];
            for (let itemIndex = 0, itemCount = count0; itemIndex < itemCount; itemIndex++) {
                let item: Severity;
                item = enumName(Severity, reader.uint8(), "Severity");
                value.severities.push(item);
            }
        }
        value.matrix = [];
        for (let itemIndex = 0, itemCount = 2; itemIndex < itemCount; itemIndex++) {
            let item: number[];
            item = [];
            for (let item1Index = 0, item1Count = 2; item1Index < item1Count; item1Index++) {
                let item1: number;
                item1 = reader.int16(true);
                item.push(item1);
            }
            value.matrix.push(item);
        }
        return value;
    },
});

